-- ============================================================================
-- مواثيق — ملف استيراد التصنيف القضائي (النجيز) — البيانات الكاملة
-- MAWATHEQ — Najiz legal taxonomy import (complete dataset)
-- ============================================================================
--
-- WHAT THIS FILE IS
--   The complete Saudi Najiz classification: 7 main specialties, 38
--   sub-specialties, 234 lawsuit types and 640 judicial requests.
--
--   DATA ONLY. It creates no table and alters no schema. It clears the four
--   taxonomy tables and re-inserts every row with its original id, inside one
--   transaction, with a prerequisite check and a post-import check that both
--   abort the whole file on failure.
--
-- REQUIRED BEFORE IMPORTING (run in this order)
--   1. database/upgrade_v59.sql   creates the najiz_* tables
--   2. database/upgrade_v63.sql   adds customer_desc_ar / customer_icon_key
--   3. THIS FILE
--   4. database/upgrade_v63.sql   AGAIN
--
--   Step 4 is required, not optional. v63 derives the customer-facing
--   descriptions from the rows that exist at the time it runs. On a database
--   where v59 has just created an empty table, the first v63 run writes nothing;
--   re-running it after this import fills all 7 descriptions and icons.
--
-- BACK UP FIRST
--   mysqldump -u USER -p DBNAME najiz_categories najiz_subcategories \
--     najiz_case_types najiz_judicial_requests > taxonomy_backup.sql
--
-- Generated from database/sources/Pasted%20text%283%29.txt
--   sha256 f6f5233153aac35684d9b6adae1fa98d7c5e8c07824d0dc5169f1ab13917b269
--   verified 7 / 38 / 234 / 640, reconciles = true
-- ============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- --- prerequisite check: abort unless every table exists -------------------
SET @missing := (
  SELECT GROUP_CONCAT(t SEPARATOR ', ') FROM (
    SELECT 'najiz_categories' t WHERE NOT EXISTS (SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='najiz_categories')
    UNION ALL SELECT 'najiz_subcategories' WHERE NOT EXISTS (SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='najiz_subcategories')
    UNION ALL SELECT 'najiz_case_types' WHERE NOT EXISTS (SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='najiz_case_types')
    UNION ALL SELECT 'najiz_judicial_requests' WHERE NOT EXISTS (SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='najiz_judicial_requests')
  ) x);
SET @msg := CONCAT('PREREQUISITE FAILED: run upgrade_v59.sql first. Missing: ', IFNULL(@missing,'?'));
SET @stmt := IF(@missing IS NULL, 'DO 0', CONCAT('SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''', @msg, ''';'));
PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;

START TRANSACTION;

-- --- clear (data only) -----------------------------------------------------
DELETE FROM najiz_judicial_requests;
DELETE FROM najiz_case_types;
DELETE FROM najiz_subcategories;
DELETE FROM najiz_categories;

-- --- najiz_categories (7 rows) ---

-- --- najiz_subcategories (38 rows) ---

-- --- najiz_case_types (234 rows) ---

-- --- najiz_judicial_requests (640 rows) ---

-- --- verification: must print 7 / 38 / 234 / 640 ---------------------------
SET @cats  := (SELECT COUNT(*) FROM najiz_categories);
SET @subs  := (SELECT COUNT(*) FROM najiz_subcategories);
SET @types := (SELECT COUNT(*) FROM najiz_case_types);
SET @reqs  := (SELECT COUNT(*) FROM najiz_judicial_requests);
SELECT @cats AS main_specialties, @subs AS sub_specialties,
       @types AS case_types, @reqs AS judicial_requests;

SET @bad := (@cats <> 7 OR @subs <> 38 OR @types <> 234 OR @reqs <> 640);
SET @stmt := IF(@bad = 0, 'DO 0', 'SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''VERIFY FAILED: expected 7/38/234/640 - the import is incomplete'';');
PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;

-- Next: re-run database/upgrade_v63.sql to fill customer_desc_ar / customer_icon_key.
